const input = $input.first().json || {};

function clean(value) {
  if (value === undefined || value === null) return null;
  const text = String(value).trim();
  return text.length ? text : null;
}

function lower(value) {
  const text = clean(value);
  return text ? text.toLowerCase() : null;
}

function normalizeDomain(value) {
  const text = clean(value);
  if (!text) return null;

  return text
    .replace(/^https?:\/\//i, "")
    .replace(/^www\./i, "")
    .split("/")[0]
    .toLowerCase();
}

function extractDomain(email, explicitDomain, website) {
  if (explicitDomain) return normalizeDomain(explicitDomain);
  if (website) return normalizeDomain(website);

  if (email && email.includes("@")) {
    return email.split("@")[1].toLowerCase();
  }

  return null;
}

const source = clean(input.source) || "website_form";
const sourceEventId = clean(input.source_event_id || input.id);

if (!sourceEventId) {
  throw new Error("Missing source_event_id. Provide a stable external ID for idempotency.");
}

const email = lower(input.email);
const companyDomain = extractDomain(email, input.company_domain || input.domain, input.website);

const fullName =
  clean(input.full_name || input.name) ||
  [clean(input.first_name || input.firstName), clean(input.last_name || input.lastName)]
    .filter(Boolean)
    .join(" ") ||
  null;

const normalizedLead = {
  source,
  source_event_id: sourceEventId,
  external_id: `${source}:${sourceEventId}`,

  first_name: clean(input.first_name || input.firstName),
  last_name: clean(input.last_name || input.lastName),
  full_name: fullName,
  email,
  phone: clean(input.phone),
  job_title: clean(input.job_title || input.title),

  company_name: clean(input.company_name || input.company),
  company_domain: companyDomain,
  website_url: clean(input.website || (companyDomain ? `https://${companyDomain}` : null)),

  message: clean(input.message || input.description || input.notes),
  budget: clean(input.budget),
  timeline: clean(input.timeline),
  country: clean(input.country),

  raw_payload: input
};

if (!normalizedLead.email && !normalizedLead.company_domain && !normalizedLead.company_name) {
  throw new Error("Lead must have at least email, company domain, or company name.");
}

return [
  {
    json: {
      external_id: normalizedLead.external_id,
      event_source: source,
      normalized_lead: normalizedLead,
      raw_payload: input
    }
  }
];

const event = $('Reserve Raw Event').first().json;

let payload = event.payload || {};

if (typeof payload === "string") {
  payload = JSON.parse(payload);
}

const lead = payload.normalized_lead || {};

return [
  {
    json: {
      run_id: event.internal_id,
      event_id: event.internal_id,
      external_id: event.external_id,
      event_source: event.event_source,
      processing_status: event.processing_status,
      normalized_lead: lead
    }
  }
];
